import type { Schedule, ScheduleDefinition, Schedules } from './types';
/**
 * A `vercel.json` schedule without its name, which is its key in `schedules`.
 * `entrypoint` schedules are built as services before Build Output.
 */
export type VercelJsonScheduleDefinition = ScheduleDefinition | (Pick<ScheduleDefinition, 'schedule' | 'timezone' | 'jitter'> & {
    /** Dockerfile or Containerfile that builds the command's image. */
    entrypoint: string;
    /** Command to run for each firing. */
    run: string[];
    /** Directory of the schedule's service; `entrypoint` is relative to it. */
    root: string;
}) | {
    /**
     * Python module whose `@schedule` handlers set the cron, timezone and
     * jitter of the schedules it creates, like `jobs.tasks`. Or a
     * JavaScript or TypeScript file, like `cleanup.ts`, whose
     * `export const config` sets them.
     */
    entrypoint: string;
    /** Directory of the schedule's service; `entrypoint` is relative to it. */
    root: string;
};
/**
 * Whether a `vercel.json` schedule runs as a service: it has an `entrypoint`
 * or a `run`. The build turns it into the service's Build Output
 * schedules.
 */
export declare function isServiceSchedule<T extends VercelJsonScheduleDefinition>(schedule: T): schedule is Extract<T, {
    entrypoint: string;
}>;
/** `vercel.json#schedules`: schedules keyed by name. */
export type VercelJsonSchedules = Record<string, VercelJsonScheduleDefinition>;
/** A `vercel.json` schedule with its name. */
export type VercelJsonSchedule = {
    name: string;
} & VercelJsonScheduleDefinition;
/** The schedules in `schedules` with their names, in key order. */
export declare function getNamedSchedules(schedules: Schedules | undefined): Schedule[];
export declare function getNamedSchedules(schedules: VercelJsonSchedules | undefined): VercelJsonSchedule[];
/**
 * The name `<service>.<name>` that a schedule a service's build declares is
 * deployed as. `error` says why the Schedules API would reject it.
 */
export declare function getServiceScheduleName(service: string, name: string): {
    deployedName: string;
    error?: string;
};
/** Named schedules keyed by name, for `schedules` in Build Output. */
export declare function toScheduleRecord(schedules: readonly Schedule[]): Schedules;
export declare function toScheduleRecord(schedules: readonly VercelJsonSchedule[]): VercelJsonSchedules;
